.hover-un {
  position: relative;
  width: fit-content;
  cursor: pointer;
  color: currentColor;
}
.hover-un::before {
  content: '';
  position: absolute;
  width: 100%;
  height: var(--border--size);
  bottom: 0.1em;
  left: 0;
  background-color: currentColor;

  -webkit-transform-origin: right;
  transform-origin: right;

  -webkit-transform: scaleX(0);
  transform: scaleX(0);

  -webkit-transition: 0.6s transform cubic-bezier(0.66, 0, 0.15, 1);
  transition: 0.6s transform cubic-bezier(0.66, 0, 0.15, 1);
}
.hover-line,
.line-hover-inner {
  --line-spacing: 1rem;
  position: relative;
  overflow: hidden;
  display: inline-block;
  vertical-align: bottom;
}
.hover-line:not([data-hover='line-inner'])::before,
.hover-line:not([data-hover='line-inner'])::after,
.line-hover-inner::before,
.line-hover-inner::after {
  content: '';
  position: absolute;
  display: block;
  bottom: 0.2em;
  width: 100%;
  height: var(--border--size);
  background-color: currentColor;
  -webkit-transition: 0.6s transform cubic-bezier(0.66, 0, 0.15, 1);
  transition: 0.6s transform cubic-bezier(0.66, 0, 0.15, 1);
}
