  20% {
    transform: scale(1.2);
    color: #373737;
  }
  100% {
    color: #d9d9d9;
    transform: scale(0.4);
  }
}
@keyframes spin-wheel {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

